import java.math.BigDecimal;
import java.math.RoundingMode;

public class PriceCalculator {
    public static BigDecimal payable(BigDecimal amount, boolean member) {
        if (amount == null || amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("amount must not be null or negative");
        }

        BigDecimal result = amount;
        if (member && amount.compareTo(new BigDecimal("100")) >= 0) {
            result = amount.multiply(new BigDecimal("0.9"));
        }

        return result.setScale(2, RoundingMode.HALF_UP);
    }
}

